// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *CurrencyForFinChargeTerms) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, CurrencyForFinChargeTermsTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "additional_fee":
			column = "additional_fee"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Currency_for_Fin_Charge_Terms", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Currency_for_Fin_Charge_Terms.%s: %w", column, err)
		}
		switch column {
		case "additional_fee":
			d, err := types.NewDecimalFromString(total)
			if err != nil {
				return fmt.Errorf("CalcSums Currency_for_Fin_Charge_Terms.%s: %w", column, err)
			}
			t.Additional_fee = d
		}
	}
	return nil
}

